WITH inventory_by_product AS (SELECT product_id, COUNT(DISTINCT quantity) AS unique_stores, MAX(quantity) AS max_quantity FROM inventory WHERE product_id IN (3, 4, 5) GROUP BY product_id) SELECT p.id, p.cost, p.category, ibp.unique_stores, ibp.max_quantity FROM products p LEFT OUTER JOIN inventory_by_product ibp ON p.id = ibp.product_id WHERE ibp.unique_stores > 9 ORDER BY p.id DESC, unique_stores;
